'use strict';
const fs=require('node:fs'),vm=require('node:vm'),assert=require('node:assert/strict');
const source=fs.readFileSync('src/ai-chat.js','utf8');
new vm.Script(source);
const fields={};let active=null;
const context={URL,document:{title:'요금 계산',getElementById:id=>fields[id]||null,querySelector:()=>active},location:{pathname:'/rates.html'}};
const helpers=source.slice(source.indexOf('function readField('),source.indexOf('function formatAnswer('));
vm.createContext(context);vm.runInContext(helpers,context);
assert.equal(context.getContext().selection,undefined,'home cannot invent a selected quote');
active={dataset:{panel:'mobile'}};
fields.carrier={tagName:'SELECT',selectedIndex:0,options:[{value:'KT',textContent:'KT'}]};
fields['monthly-total']={textContent:'212,827원'};
assert.equal(context.getContext().selection,undefined,'a monthly amount alone must not make an incomplete mobile quote valid');
for(const [id,text] of [['device-select','아이폰 듀오 256GB'],['plan-select','베이직 80']])fields[id]={tagName:'SELECT',selectedIndex:0,options:[{value:id,textContent:text}]};
fields['join-type']={textContent:'번호이동'};fields['calc-summary']={textContent:'24개월'};
assert.match(context.getContext().selection,/아이폰 듀오.*베이직 80.*212,827원/);
fields['monthly-total'].textContent='—';assert.equal(context.getContext().selection,undefined,'a cleared calculation hides the context and contextual question');
const old=[{role:'assistant',content:'이전 답변'}];
const payload=context.makePayload('요금 질문',old,{active_tab:'mobile'});
assert.equal(old.length,1,'failed attempts can retry without mutating history');
assert.equal(payload.history.length,2);assert.equal(payload.question,'요금 질문');
assert.equal(context.makePayload('질문',Array.from({length:12},()=>({role:'user',content:'이전'})),{}).history.length,8);
(async()=>{
 context.fetch=async()=>({ok:true,json:async()=>({answer:'공개 안내'})});assert.equal(await context.requestAnswer(payload),'공개 안내');
 context.fetch=async()=>({ok:false,json:async()=>({error:'실패'})});await assert.rejects(context.requestAnswer(payload));
 context.fetch=async()=>({ok:true,json:async()=>({})});await assert.rejects(context.requestAnswer(payload),'empty answers must offer retry');
 context.fetch=async()=>{const e=new Error('timeout');e.name='AbortError';throw e;};await assert.rejects(context.requestAnswer(payload),{name:'AbortError'});
 assert.ok(source.includes("if(!retry)addMessage(question,'user')"),'retry must not add duplicate user bubbles');
 assert.ok(source.includes("button.textContent='다시 시도'"));
 const created=[];
 context.document.createTextNode=text=>({textContent:text});context.document.createElement=tag=>{created.push(tag);return {textContent:''};};
 vm.runInContext(source.slice(source.indexOf('function formatAnswer('),source.indexOf('function addMessage(')),context);
 const children=[],node={appendChild:child=>children.push(child)};
 context.formatAnswer(node,'**월 30,000원** <img src=x onerror=alert(1)>');
 assert.deepEqual(created,['strong']);assert.equal(children.map(x=>x.textContent).join(''),'월 30,000원 <img src=x onerror=alert(1)>');
 assert.ok(source.includes('else bubble.textContent=text'),'user input remains plain text');
 console.log('AI chat: complete quote context, cleared state, bounded history, success/failure/timeout and retry contracts PASS');
})().catch(error=>{console.error(error);process.exitCode=1;});
